@testable import EversenseKit
import Testing

struct PackageTest {
    @Test func glucoseTest() async throws {
        let data =
            Data(
                hexString: ""
            ) ?? Data()

        Eversense365.sensorIdLength = 0x0A
        let glucoseData = Eversense365.GetGlucoseDataPacket()
        let result = glucoseData.parseResponse(data: data)

        #expect(result.glucoseInMgDl != 0xFFFF)
    }

    @Test func signalStrength() async throws {
        let data = Data(hexString: "421B010A000000000000000000009C622EB80000000074083B73034003") ?? Data()

        Eversense365.sensorIdLength = 0x0A
        let signalStrength = Eversense365.GetSignalStrenghtPacket()
        let result = signalStrength.parseResponse(data: data)

        #expect(result.signalStrength != SignalStrength.NoSignal)
    }

    @Test func calibrationData() async throws {
        let data = Data(hexString: "421d03005eb38e50c30000000104000000000000ac4bb32bc30000006d0118009b265db3a42bc3000000") ??
            Data()

        Eversense365.sensorIdLength = 0x0A
        let calibrationData = Eversense365.GetCalibrationInfoPacket()
        let result = calibrationData.parseResponse(data: data)

        #expect(result.currentPhase != .DEBUG)
    }

    @Test func sensorInformation() async throws {
        let data =
            Data(
                hexString: ""
            ) ?? Data()

        let sensorInformation = Eversense365.GetSensorInformationPacket()
        let result = sensorInformation.parseResponse(data: data)

        #expect(result.communicationProtocolVersion >= 1.06)
        #expect(result.sensorIdLength == 0x0A)
    }

    @Test func glucoseLog() async throws {
        let data =
            Data(
                hexString: ""
            ) ?? Data()

        Eversense365.sensorIdLength = 0x0A
        let packet = Eversense365.GetGlucoseLogValuesPacket(from: 38166, to: 38217)
        let result = packet.parseResponse(data: data)

        #expect(!result.glucoseHistory.isEmpty)
    }

    @Test func calibrationLog() async throws {
        let data =
            Data(
                hexString: ""
            ) ?? Data()

        Eversense365.sensorIdLength = 0x0A
        let packet = Eversense365.GetCalibrationLogPacket(from: 32, to: 52)
        let result = packet.parseResponse(data: data)

        #expect(!result.calibrationHistory.isEmpty)
    }

    @Test func activeAlarms() async throws {
        let data = Data(hexString: "42220139002c") ?? Data()

        Eversense365.sensorIdLength = 0x0A
        let packet = Eversense365.GetActiveAlarmsPacket(currentGlucose: 180)
        let result = packet.parseResponse(data: data)

        #expect(result.count == 1)
    }

    @Test func pushAlarm() async throws {
        let data = Data(hexString: "44034700006d23c600000068006a000100e8086a000300000000c0") ?? Data()

        Eversense365.sensorIdLength = 0x0A
        let packet = Eversense365.PushAlarmWithDataPacket(currentGlucose: 180)
        let result = packet.parseResponse(data: data)

        #expect(result.alarmRaw > 0)
    }

    @Test func currentGlucoseOld() async throws {
        let data = Data(hexString: "88114d003434f3a000ba0000001000004a06625a") ?? Data()
        let packet = EversenseE3.GetCurrentGlucosePacket()
        let result = packet.parseResponse(data: data)

        #expect(result.glucoseInMgDl == 0)
    }

    @Test func keepAlive() async throws {
        let data = Data(hexString: "44028ba79fe2c40000005851109fe2c4000000232b82e2c4000000") ?? Data()
        let packet = Eversense365.PushKeepAlivePacket()
        let result = packet.parseResponse(data: data)

        #expect(result.batteryLevel != 0)
    }
}
